// Turns the Figma variables export (tokens/figma-variables.json) into CSS custom properties.
// Source of truth is Figma. This file is generated output only, so never edit src/tokens/tokens.css by hand.
//
// The CSS variable names come from the "WEB code syntax" set on each Figma variable, so a designer
// renaming a token's code syntax in Figma is the only way a token name changes in code.
//
// At real scale I would swap this ~100 line script for Style Dictionary or Tokens Studio transforms.
// It is deliberately small here so every step is easy to read and explain.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const src = JSON.parse(readFileSync('tokens/figma-variables.json', 'utf8'));

const cssNameOf = (variable) => {
  const syntax = variable.codeSyntax?.WEB;
  const match = syntax && syntax.match(/^var\((--[\w-]+)\)$/);
  if (!match) throw new Error(`Variable "${variable.name}" has no valid WEB code syntax: ${syntax}`);
  return match[1];
};

// Index every variable by its Figma name so aliases can be resolved.
const byName = new Map();
for (const c of src.collections) for (const v of c.variables) byName.set(v.name, { ...v, collection: c.name });

const px = (n) => `${n}px`;
const resolveToHex = (variable, mode) => {
  let v = variable;
  let guard = 0;
  while (true) {
    const key = v.values[mode] !== undefined ? mode : Object.keys(v.values)[0];
    const val = v.values[key];
    if (val && typeof val === 'object' && 'alias' in val) {
      const next = byName.get(val.alias);
      if (!next) throw new Error(`Alias "${val.alias}" referenced by "${v.name}" does not exist`);
      v = next;
      if (++guard > 10) throw new Error(`Alias loop at ${variable.name}`);
    } else return val;
  }
};

const lines = { root: [], light: [], dark: [] };
const resolved = { light: {}, dark: {}, static: {} };

for (const c of src.collections) {
  for (const v of c.variables) {
    const name = cssNameOf(v);
    if (c.name === 'Primitives') {
      lines.root.push(`  ${name}: ${v.values.Value};`);
      resolved.static[name] = v.values.Value;
    } else if (c.name === 'Color') {
      for (const [mode, bucket] of [['Light', 'light'], ['Dark', 'dark']]) {
        const val = v.values[mode];
        if (!val || !('alias' in val)) throw new Error(`Semantic token "${v.name}" must alias a primitive in ${mode} mode`);
        const target = byName.get(val.alias);
        if (!target || target.collection !== 'Primitives') throw new Error(`"${v.name}" must alias a Primitive, got "${val.alias}"`);
        lines[bucket].push(`  ${name}: var(${cssNameOf(target)});`);
        resolved[bucket][name] = resolveToHex(v, mode);
      }
    } else {
      // Spacing, Radius, Typography: single mode numbers become px values.
      const value = px(v.values.Value);
      lines.root.push(`  ${name}: ${value};`);
      resolved.static[name] = value;
    }
  }
}

const header = `/* AUTO-GENERATED by scripts/build-tokens.mjs from tokens/figma-variables.json.
 * Do not edit by hand. Change the variable in Figma, re-export, then run: npm run tokens
 * Figma file: ${src.fileKey} */\n`;

const css = `${header}
:root {
${lines.root.join('\n')}
}

/* Light is the default. */
:root,
[data-theme="light"] {
${lines.light.join('\n')}
}

/* Explicit dark mode. */
[data-theme="dark"] {
${lines.dark.join('\n')}
}

/* Respect the OS setting when the page has not chosen a theme. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]):not([data-theme="dark"]) {
${lines.dark.map((l) => '  ' + l).join('\n')}
  }
}
`;

mkdirSync('src/tokens', { recursive: true });
writeFileSync('src/tokens/tokens.css', css);
writeFileSync('src/tokens/resolved.json', JSON.stringify(resolved, null, 2) + '\n');
console.log(
  `tokens: ${lines.root.length} static, ${lines.light.length} semantic x 2 modes -> src/tokens/tokens.css and resolved.json`
);
